-- ============================================================
-- FILE: migrations/0003_discord.sql
-- ============================================================

-- The Observance — Discord service schema
-- 0003_discord.sql
--
-- The Discord bot connects with the service_role key (server-side only), which
-- BYPASSES RLS. It links Discord users to existing Minecraft players and reads
-- pre-authored whisper hints.
--
-- Security model (consistent with 0001_init.sql):
--   * RLS is enabled on every new table.
--   * service_role bypasses RLS — the bot can do anything.
--   * NO anon / authenticated policies are added for `hints` — it is service-role
--     ONLY (the pre-authored hint bodies are spoilers and never reach the public
--     or the dashboard's authenticated admins through this table).
--
-- Everything runs in the `public` schema.

begin;

-- ---------------------------------------------------------------------------
-- players.discord_id — links a Discord user to a Minecraft player.
-- Nullable: a player may exist without ever linking Discord.
-- Unique: a Discord account maps to at most one player.
-- ---------------------------------------------------------------------------

alter table public.players
  add column if not exists discord_id text unique;

-- ---------------------------------------------------------------------------
-- hints — the PRE-AUTHORED whisper hints, keyed by (puzzle_key, tier).
-- Seeded later from the sealed arc (NOT committed to code). The bot only READS
-- this table; it is left empty here.
-- ---------------------------------------------------------------------------

create table if not exists public.hints (
  id         bigserial primary key,
  puzzle_key text not null,
  tier       int  not null,
  body       text not null,
  unique (puzzle_key, tier)
);

-- Fast lookup path used by the bot: getHint(puzzle_key, tier).
create index if not exists idx_hints_puzzle_tier
  on public.hints (puzzle_key, tier);

-- ---------------------------------------------------------------------------
-- Row Level Security — enabled, service-role ONLY.
-- No anon and no authenticated policies: only the service_role (which bypasses
-- RLS entirely) can read or write `hints`.
-- ---------------------------------------------------------------------------

alter table public.hints enable row level security;

-- Defensive: ensure no blanket grants leak from Supabase defaults.
revoke all on public.hints from anon;
revoke all on public.hints from authenticated;
revoke all on sequence public.hints_id_seq from anon;
revoke all on sequence public.hints_id_seq from authenticated;

commit;


-- ============================================================
-- FILE: migrations/0004_oracle.sql
-- ============================================================

-- The Observance — Oracle schema (the non-linear clue web).
-- 0004_oracle.sql
--
-- The ORACLE is the closed loop: a player who solves a forged clue submits the
-- plaintext answer (in Discord #the-record OR on an in-world answer-sign), the
-- bot/plugin matches it against the OPEN puzzles, and — if it matches — the world
-- answers. This migration creates the authoring + resolution tables that loop
-- runs on.
--
-- DIFFICULTY: HARD, NON-LINEAR WEB. Many puzzles are `active` at once. A single
-- answer resolves to ONE of five OUTCOME TYPES (next_clue | lore | dead_end |
-- side_quest | main_beat). Multiple correct answers per puzzle are supported
-- (accepted_answers is an array). Some clues advance, some only reveal lore,
-- some are TRUE-BUT-NOT-A-DOOR dead ends (red-herring texture the watcher
-- acknowledges in voice but that leads nowhere), some open optional side quests,
-- some fire a main story beat. Authors wire ANY of these per row.
--
-- Security model (consistent with 0001_init.sql / 0003_discord.sql):
--   * RLS enabled on every new table.
--   * service_role bypasses RLS — the bot/plugin (service-role, server-side) can
--     do anything; NO anon / authenticated policies are added. `accepted_answers`
--     are spoilers and must never reach the public or the dashboard admins through
--     these tables.
--
-- Everything runs in the `public` schema.

begin;

-- ===========================================================================
-- 0. beat_queue reconciliation — additive, non-breaking.
--
-- The plugin (data/rows/BeatQueueRow.java + beats/RealBeatEnactor.java) ALREADY
-- reads `mc_uuid`, `site_id`, `priority` and writes status 'failed', and
-- fetchActionableBeats() orders by `priority`. The canonical 0001 beat_queue has
-- only `target` and a status check WITHOUT 'failed'. The oracle's `unlock` beats
-- must be enqueued in a shape the plugin can read + target, so we bring the live
-- schema up to the contract the plugin already speaks. Existing `target`-based
-- inserts (e.g. /whisper) keep working untouched.
-- ===========================================================================

alter table public.beat_queue
  add column if not exists mc_uuid  text,
  add column if not exists site_id  text,
  add column if not exists priority int;

-- Widen the status check to include 'failed' (the plugin's terminal state for a
-- beat whose enactor threw). Drop the old constraint by its default name, re-add.
do $$
begin
  if exists (
    select 1 from pg_constraint
    where conrelid = 'public.beat_queue'::regclass
      and conname  = 'beat_queue_status_check'
  ) then
    alter table public.beat_queue drop constraint beat_queue_status_check;
  end if;
end $$;

alter table public.beat_queue
  add constraint beat_queue_status_check
  check (status in ('pending','approved','skipped','fired','failed'));

-- APPROVAL GATE: the plugin poller fires `status=eq.approved` ONLY, ordered by
-- priority desc, created_at asc — so `pending` beats wait for a human to approve
-- them in the dashboard (the showrunner CONFIRM mode + the Accepting trigger).
-- The dashboard, in turn, lists the `pending` beats as its approval queue. This
-- partial index covers BOTH access paths (the poller's approved read and the
-- dashboard's pending read), so both stay index-served.
create index if not exists idx_beat_queue_actionable
  on public.beat_queue (priority desc nulls last, created_at asc)
  where status in ('pending','approved');

-- ===========================================================================
-- 1. puzzles — the authored clue web. One row per forged clue.
--
-- puzzle_key is the STABLE FNV-1a id from forgeClue() (e.g. "clue_caesar_1a2b3c4d").
-- It is the SAME key hints (0003), whisper_events, and solves are addressed by, so
-- the whole loop points at one puzzle.
-- ===========================================================================

create table if not exists public.puzzles (
  -- the forgeClue() FNV-1a key — the join point for the entire web.
  puzzle_key       text primary key,

  -- author-facing label (spoiler; never shown to players in voice).
  title            text not null,

  -- normalized accepted solutions. MULTIPLE correct answers supported. Each
  -- entry MUST already be stored in normalized form (see ORACLE.md §normalize):
  -- case-folded, trimmed, internal whitespace collapsed to single spaces,
  -- punctuation stripped. The resolver normalizes the player's raw input the same
  -- way and tests set-membership against this array.
  accepted_answers text[] not null check (array_length(accepted_answers, 1) >= 1),

  -- what a correct answer DOES. The web's branching dimension:
  --   next_clue  — advances: reveals/forges the next clue (a door).
  --   lore       — reveals story/character info; NO progression (not a door).
  --   dead_end   — a TRUE answer deliberately not a door: the watcher
  --                acknowledges it in voice, it leads nowhere. red-herring texture.
  --   side_quest — opens an optional thread (a door to an off-spine branch).
  --   main_beat  — fires a main-story event/unlock (a door to the spine).
  outcome_type     text not null
                     check (outcome_type in
                       ('next_clue','lore','dead_end','side_quest','main_beat')),

  -- the resolution recipe. Shape (all keys optional unless noted):
  --   {
  --     "voice_key": "oracleNextClue",        -- which voice.ts line speaks the reply (REQUIRED)
  --     "voice_args": { "name": "...", ... }, -- optional args spread into the voice fn
  --     "next_puzzle_key": "clue_book_…",     -- for next_clue / side_quest: the puzzle this opens
  --     "set_flags": { "found_well": true },  -- optional arc_state.flags to set on solve
  --     "beat": {                             -- OPTIONAL in-world reward to enqueue (see ORACLE.md)
  --       "type": "unlock",                   --   beat_queue.type
  --       "mc_uuid": "{solver}",              --   "{solver}" placeholder → resolved to the solving player's uuid
  --       "site_id": "well_shrine",           --   optional sites.yml id
  --       "priority": 10,                     --   optional ordering hint
  --       "payload": { "step": "door_open",   --   the UnlockBeat dispatcher payload
  --                    "step_payload": { "radius": 3, "open": true } }
  --     }
  --   }
  -- dead_end rows carry voice_key only (the acknowledgement) and NO next_puzzle_key
  -- and NO beat — it is true, it is heard, it opens nothing.
  outcome_payload  jsonb not null default '{}'::jsonb,

  -- author-facing position on the web (act/rung). For ordering/visualization only;
  -- the resolver does NOT gate on it (the web is non-linear). Defaults to 0.
  movement         int not null default 0,

  -- is this puzzle OPEN for answers? The resolver only ever matches against rows
  -- where active = true. Authors flip this to stage/retire branches of the web.
  active           boolean not null default true,

  -- per-puzzle attempt cap (anti-brute-force, on top of the global rate limit).
  -- NULL = no per-puzzle cap (the global token bucket still applies). When set,
  -- a player who reaches it is met with in-voice silence/withholding, never a hint.
  max_attempts     int,

  created_at       timestamptz not null default now()
);

-- Resolver hot path: "give me the OPEN puzzles to match this answer against".
create index if not exists idx_puzzles_active
  on public.puzzles (active)
  where active = true;

-- ===========================================================================
-- 2. solves — the replay guard. One row per (puzzle, player) that resolved.
--
-- IDEMPOTENT: unique(puzzle_key, player_id) means solving the same puzzle twice
-- cannot double-fire its unlock. The resolver INSERTs here with ON CONFLICT DO
-- NOTHING *before* enqueuing the beat; only a genuinely-new insert proceeds to
-- enqueue the reward.
-- ===========================================================================

create table if not exists public.solves (
  id           bigserial primary key,

  -- which puzzle was solved.
  puzzle_key   text not null references public.puzzles(puzzle_key) on delete cascade,

  -- WHO solved it. player_id is the canonical link; mc_uuid + discord_id are
  -- denormalized for audit and for whichever surface (in-world / discord) the
  -- solve arrived on. player_id is NOT NULL (a solve is always a known keeper).
  player_id    uuid not null references public.players(id) on delete cascade,
  mc_uuid      text,
  discord_id   text,

  -- how many attempts this player made before the solve landed (audit/balance).
  attempt_count int not null default 1,

  solved_at    timestamptz not null default now(),

  -- the replay guard: one solve per puzzle per player.
  unique (puzzle_key, player_id)
);

create index if not exists idx_solves_player
  on public.solves (player_id);

-- ===========================================================================
-- 3. answer_attempts — append-only audit + rate-limit substrate.
--
-- EVERY attempt is logged (matched or not) so the resolver can enforce cooldown
-- + token bucket and so authors can see brute-force pressure. Never reveals which
-- PART was right — it records the whole normalized string and a single matched bool.
-- ===========================================================================

create table if not exists public.answer_attempts (
  id          bigserial primary key,

  -- which puzzle this attempt matched, if any. NULL when the input matched no
  -- open puzzle (ordinary chat the watcher stays silent on, or a true miss).
  puzzle_key  text references public.puzzles(puzzle_key) on delete set null,

  -- who attempted. player_id may be NULL for an unlinked discord user whose
  -- message was scanned in #the-record (we still rate-limit them by discord_id).
  player_id   uuid references public.players(id) on delete set null,
  mc_uuid     text,
  discord_id  text,

  -- where it came from: 'discord' (#the-record scan or future command) or 'world'
  -- (an in-world answer-sign). Used to scope rate limits per surface if desired.
  surface     text check (surface in ('discord','world')),

  -- the player's exact input (audit) and its normalized form (what was matched).
  raw         text,
  normalized  text,

  -- did `normalized` hit an accepted_answers entry of an OPEN puzzle?
  matched     boolean not null default false,

  at          timestamptz not null default now()
);

-- Rate-limit lookups: "how many attempts has this player made in the last window?"
-- Two indexes — by linked player, and by raw discord_id for unlinked scanners.
create index if not exists idx_answer_attempts_player_at
  on public.answer_attempts (player_id, at desc);

create index if not exists idx_answer_attempts_discord_at
  on public.answer_attempts (discord_id, at desc);

create index if not exists idx_answer_attempts_mc_at
  on public.answer_attempts (mc_uuid, at desc);

-- ===========================================================================
-- 4. Row Level Security — enabled, service-role ONLY (spoiler tables).
-- No anon / authenticated policies: only service_role (which bypasses RLS) reads
-- or writes these. Defensive revokes mirror 0003_discord.sql.
-- ===========================================================================

alter table public.puzzles         enable row level security;
alter table public.solves          enable row level security;
alter table public.answer_attempts enable row level security;

revoke all on public.puzzles         from anon;
revoke all on public.puzzles         from authenticated;
revoke all on public.solves          from anon;
revoke all on public.solves          from authenticated;
revoke all on public.answer_attempts from anon;
revoke all on public.answer_attempts from authenticated;

revoke all on sequence public.solves_id_seq          from anon;
revoke all on sequence public.solves_id_seq          from authenticated;
revoke all on sequence public.answer_attempts_id_seq from anon;
revoke all on sequence public.answer_attempts_id_seq from authenticated;

commit;


-- ============================================================
-- FILE: migrations/0005_threads.sql
-- ============================================================

-- The Observance — 0005_threads.sql
-- The reconstruction layer (the Recovery Archive), the side-quest breadth, the
-- discover-by-punishment custom state, and the NPC dialogue state. All additive; runs
-- after 0004_oracle.sql. Closes red-team blocker B-7 (the thread-layer coverage skeleton)
-- and the INTEGRATION §5 data-model additions.
--
-- Security model (identical to 0004): RLS enabled on every new table; service_role bypasses
-- it; NO anon / authenticated policies (these carry spoiler structure + per-player state).
--
-- Everything in the `public` schema. Idempotent (create … if not exists, add column if not
-- exists, on conflict do nothing) — safe to re-run.

begin;

-- ===========================================================================
-- 1. threads — the five reconstruction threads (the Recovery Archive columns).
--    Progress = these filling in, NOT a step counter (the rumor→verify skeleton).
--    Canonical keys mirror forge/canon.ts THREADS; a thread-coverage self-test asserts
--    every puzzles.thread_key / thread_cards.thread_key is one of these.
-- ===========================================================================

create table if not exists public.threads (
  thread_key      text primary key,            -- who | place | happened | surface | human
  label           text not null,               -- player-facing column title
  color           text not null,               -- card tint (amber/green/red/grey/black)
  sort_order      int  not null default 0,
  created_at      timestamptz not null default now()
);

-- Seed the five canonical threads (the questions the whole game answers).
insert into public.threads (thread_key, label, color, sort_order) values
  ('who',      'who they were',              'amber', 1),
  ('place',    'what this place was',        'green', 2),
  ('happened', 'what happened',              'red',   3),
  ('surface',  'what is on the surface',     'grey',  4),
  ('human',    'were they human',            'black', 5)
on conflict (thread_key) do nothing;

-- ===========================================================================
-- 2. thread_cards — the ship-log: every find is a place-anchored card that clusters
--    under a thread. Rumor cards flip to verified/contradicted on arrival; conditional
--    reveals expand once referenced cards are found. Authored content lands here.
-- ===========================================================================

create table if not exists public.thread_cards (
  card_key            text primary key,
  thread_key          text not null references public.threads(thread_key) on delete cascade,
  title               text not null,
  -- the in-character body comes from voice.ts / the corpus via a key, never inline english.
  body_voice_key      text,
  -- where in the world this card is anchored (a sites.yml id), if any.
  anchor_site_id      text,
  -- 'rumor' = heard secondhand (a dotted line to an unvisited place); 'explore' = verified
  -- firsthand on-site. Arriving can flip a rumor to 'verified' or 'contradicted'.
  card_kind           text not null default 'explore'
                        check (card_kind in ('rumor','explore','verified','contradicted')),
  -- cards this one references (the citation web); a conditional reveal expands once these
  -- are all found (alt_text_condition names the gate).
  references_card_key text[] not null default '{}',
  -- the solve (puzzle_key) that surfaces this card, if it is solve-gated.
  revealed_by_solve   text,
  -- the named condition under which alt/expanded text unlocks (e.g. 'found:warden-tag').
  alt_text_condition  text,
  sort_order          int not null default 0,
  created_at          timestamptz not null default now()
);

create index if not exists idx_thread_cards_thread on public.thread_cards (thread_key, sort_order);

-- ===========================================================================
-- 3. side_quests — the breadth layer (off-spine threads that GATE NOTHING; they pay
--    lore/atmosphere/items/time). The longevity engine's non-spine volume.
-- ===========================================================================

create table if not exists public.side_quests (
  quest_key       text primary key,
  thread_key      text references public.threads(thread_key) on delete set null,
  -- the puzzle/row that opens it (a side_quest-outcome node), if any.
  entry_puzzle_key text,
  -- what it pays (free-text authoring note; the actual reward is the node's outcome).
  reward          text,
  -- BREADTH INVARIANT: a side quest must never gate spine progress.
  gates_progress  boolean not null default false check (gates_progress = false),
  -- tier: ambient (just found) | rumored (pointed at, verify) | keyed (needs a side-cipher).
  tier            text not null default 'ambient'
                    check (tier in ('ambient','rumored','keyed')),
  -- rough authored play-minutes (the HOURS ledger; red-team B-1: budget time, not nodes).
  est_minutes     int not null default 0,
  created_at      timestamptz not null default now()
);

-- ===========================================================================
-- 4. punishment_state — the spine of discover-by-punishment (Req 3). Per (player, way):
--    the custom pass escalates a soft, reversible toll on repeated transgression until the
--    player DECIPHERS the way (from a teaching surface) and stops. NOT a hard punishment —
--    tolls take warmth, not progress (INV-8).
-- ===========================================================================

create table if not exists public.punishment_state (
  id                 bigserial primary key,
  player_id          uuid not null references public.players(id) on delete cascade,
  -- canonical the_-prefixed custom key (forge/canon.ts CUSTOM_KEYS).
  custom_key         text not null,
  transgression_count int not null default 0,
  last_toll_at       timestamptz,
  -- 0 none, 1 deniable(stage A), 2 named(stage B / warn). escalates with repetition.
  toll_tier          int not null default 0,
  -- true once the player has performed the way (learned it); the toll then clears.
  deciphered         boolean not null default false,
  -- which in-world clue teaches this way (a sites.yml id / doc) — so the loop is fair.
  teaching_site_id   text,
  updated_at         timestamptz not null default now(),
  unique (player_id, custom_key)
);

create index if not exists idx_punishment_player on public.punishment_state (player_id);

-- ===========================================================================
-- 5. npc_dialogue_state + npc_quests — per-player NPC conversation + fetch/return state,
--    so surface NPCs (Citizens2) remember and branch on the dossier. The Iss tree flips
--    warm→cold on arc_state.flags.iss_caught.
-- ===========================================================================

create table if not exists public.npc_dialogue_state (
  id          bigserial primary key,
  player_id   uuid not null references public.players(id) on delete cascade,
  npc_key     text not null,              -- aro | wenna | coll | dob | old-pell | …
  -- conversation cursor + any per-NPC flags (jsonb so dialogue trees evolve without migration).
  state       jsonb not null default '{}'::jsonb,
  updated_at  timestamptz not null default now(),
  unique (player_id, npc_key)
);

create table if not exists public.npc_quests (
  id          bigserial primary key,
  player_id   uuid not null references public.players(id) on delete cascade,
  quest_key   text not null,
  status      text not null default 'offered'
                check (status in ('offered','active','done','failed')),
  updated_at  timestamptz not null default now(),
  unique (player_id, quest_key)
);

create index if not exists idx_npc_dialogue_player on public.npc_dialogue_state (player_id);
create index if not exists idx_npc_quests_player    on public.npc_quests (player_id);

-- ===========================================================================
-- 6. puzzles column adds — tag each node to a thread + (optionally) the way it teaches.
--    Lets the Recovery Archive cluster a solved node's card, and links the cipher↔custom
--    layers. Additive + nullable; existing rows unaffected.
-- ===========================================================================

alter table public.puzzles
  add column if not exists thread_key    text references public.threads(thread_key),
  add column if not exists teaches_custom text;

create index if not exists idx_puzzles_thread on public.puzzles (thread_key) where thread_key is not null;

-- ===========================================================================
-- 7. Row Level Security — service-role ONLY (spoiler structure + per-player state).
-- ===========================================================================

alter table public.threads            enable row level security;
alter table public.thread_cards       enable row level security;
alter table public.side_quests        enable row level security;
alter table public.punishment_state   enable row level security;
alter table public.npc_dialogue_state enable row level security;
alter table public.npc_quests         enable row level security;

revoke all on public.threads            from anon;  revoke all on public.threads            from authenticated;
revoke all on public.thread_cards       from anon;  revoke all on public.thread_cards       from authenticated;
revoke all on public.side_quests        from anon;  revoke all on public.side_quests        from authenticated;
revoke all on public.punishment_state   from anon;  revoke all on public.punishment_state   from authenticated;
revoke all on public.npc_dialogue_state from anon;  revoke all on public.npc_dialogue_state from authenticated;
revoke all on public.npc_quests         from anon;  revoke all on public.npc_quests         from authenticated;

revoke all on sequence public.punishment_state_id_seq   from anon;  revoke all on sequence public.punishment_state_id_seq   from authenticated;
revoke all on sequence public.npc_dialogue_state_id_seq from anon;  revoke all on sequence public.npc_dialogue_state_id_seq from authenticated;
revoke all on sequence public.npc_quests_id_seq         from anon;  revoke all on sequence public.npc_quests_id_seq         from authenticated;

commit;


-- ============================================================
-- FILE: migrations/0006_requires_flags.sql
-- ============================================================

-- The Observance — 0006_requires_flags.sql
-- THE KEYSTONE. Adds the one column the entire non-linear progression depends on and
-- that no prior migration ever created: `puzzles.requires_flags`.
--
-- Why this file is the single most important fix in the overhaul (see design/OVERHAUL.md §2):
-- the seeds already author a complete, internally-consistent flag-gate — metapuzzle_seed.sql
-- §2 sets requires_flags on every back-half row and flips them active, and progression_seed.sql
-- gates the Nether/End lanes the same way. BUT every one of those UPDATEs sits inside a
--   `do $$ begin if exists (… column_name = 'requires_flags') then … else raise notice … end $$;`
-- guard, because the column didn't exist. So they all silently no-op: nine M4/Seventh rows that
-- ship active=false stay dark forever, and base-docket-reread-auto ships active=true meant to be
-- HELD CLOSED by a gate that isn't there, so it leaks its M4 answers from minute one.
--
-- This migration creates the column. After it lands, RE-RUN the seeds (puzzles_seed.sql,
-- metapuzzle_seed.sql, progression_seed.sql) so the guarded activation lane takes effect — the
-- guards now see the column and apply instead of `raise notice`. The whole back half lights up.
--
-- THE GATE CONTRACT (the storylet precondition system; OVERHAUL.md §3):
--   A row is OPEN  ⟺  active = true  AND  every key in requires_flags is truthy in arc_state.flags.
--   `getOpenPuzzles` (discord/src/db/repo.ts) and the Java OracleResolver.firstMatch BOTH AND-test
--   it. An empty `{}` (the default) means "no gate" — so every existing ungated row is unchanged.
--
-- Security model (identical to 0004/0005): RLS already enabled on puzzles; service_role bypasses;
-- no anon/authenticated policies. Additive + idempotent (add column if not exists) — safe to re-run.

begin;

-- ===========================================================================
-- 1. puzzles.requires_flags — the storylet precondition. A flat jsonb object of
--    { flag_key: true } that must ALL be truthy in arc_state.flags for the row to open.
--    Default '{}' = ungated (the open condition collapses to just active=true), so adding
--    the column changes the behavior of NO existing row until a seed sets a non-empty value.
-- ===========================================================================

alter table public.puzzles
  add column if not exists requires_flags jsonb not null default '{}'::jsonb;

comment on column public.puzzles.requires_flags is
  'Storylet gate (OVERHAUL.md §3): a flat {flag:true} object; the row is open iff active=true '
  'AND every key here is truthy in arc_state.flags. Default {} = ungated. AND-tested by '
  'getOpenPuzzles (TS) and OracleResolver.firstMatch (Java). Keep FLAT — the merge is shallow.';

-- A partial expression index is unnecessary: `puzzles` is a tiny table read in full each resolve
-- (getOpenPuzzles selects all active rows, then the app AND-tests requires_flags against the single
-- arc_state row's flags). No query filters on requires_flags in SQL, so no index is added here.

-- ===========================================================================
-- 2. observance_merge_arc_flags(p_flags) — ATOMIC shallow merge of the single
--    arc_state.flags blob. Kills the read-modify-write clobber in repo.setArcFlags:
--    a concurrent Discord solve + in-world solve (or two Discord solves) each doing
--    SELECT-then-UPDATE could drop one set's keys; the jsonb `||` union performed
--    server-side in ONE statement cannot. Right operand wins on key conflict — exactly
--    right for our flat {flag:true} shape (DOSSIER #A2). Flags MUST stay flat (the merge
--    is shallow; a nested object would be wholesale-overwritten, not deep-merged).
-- ===========================================================================

create or replace function public.observance_merge_arc_flags(p_flags jsonb)
returns jsonb
language sql
security definer
set search_path = public
as $$
  update public.arc_state
     set flags = flags || coalesce(p_flags, '{}'::jsonb),
         updated_at = now()
   where id = 1
  returning flags;
$$;

comment on function public.observance_merge_arc_flags(jsonb) is
  'Atomic shallow merge into arc_state.flags (id=1): flags = flags || p_flags in one '
  'statement (no read-modify-write clobber). Keep the flags object FLAT. Called by '
  'repo.setArcFlags via .rpc().';

-- Lock the function down to service_role only (the bot/showrunner run as service_role;
-- there is no anon/authenticated path that should mutate the arc). REVOKE the default
-- PUBLIC EXECUTE that `create function` grants, then GRANT to service_role explicitly.
revoke all on function public.observance_merge_arc_flags(jsonb) from public;
grant execute on function public.observance_merge_arc_flags(jsonb) to service_role;

commit;


-- ============================================================
-- FILE: migrations/0007_answer_kind.sql
-- ============================================================

-- The Observance — 0007_answer_kind.sql
-- Adds `puzzles.answer_kind` — the coarse resolution modality of a puzzle's answer, so the
-- seed can DECLARE (and the tooling can reason about) which rows are typed-phrase solves vs
-- which are produced by an in-world PLUGIN listener that sets the puzzle's flag directly.
--
-- Why this column exists (design/PUZZLE-DESIGNS.md §1 / PUZZLES.md §4): the diverse-expansion
-- puzzles span many modalities. Some resolve by a TYPED phrase the resolver matches against
-- accepted_answers (answer_kind='phrase' — today's only resolver path, and the DEFAULT). Others
-- resolve by a body action, a deposited object, a spoken line, or an on-site bearing — those are
-- detected by a plugin PRODUCER listener that posts an opaque sentinel token OR sets the puzzle's
-- flag directly. The resolver needs NO new branch for the non-typed kinds: it keeps matching
-- normalized phrases / opaque tokens exactly as it does today. answer_kind is DECLARATIVE metadata
-- that records the intent and lets a later plugin round know which rows need a producer.
--
--   answer_kind ∈ { phrase | coords | url_token | behavior | object | spoken | code | none }
--     phrase     — typed free text matched against accepted_answers (DEFAULT; the resolver path)
--     coords     — an on-site destination WORD found by following a bearing (typed; INV-14)
--     url_token  — a decoded record-website path token (typed)
--     code       — a lock/dial/comparator combination the plugin reads (plugin-produced)
--     behavior   — a body action (bow / stand-at-anchor / silence) the plugin detects
--     object     — a container-content / deposit the plugin detects
--     spoken     — a voice-chat line the Observer Engine hears
--     none       — a comprehension beat with nothing to submit (the world reacts)
--
-- ADDITIVE + IDEMPOTENT: `add column if not exists … default 'phrase'` — every existing row is
-- unaffected (they are all typed-phrase solves, the historical implicit default). Safe to re-run.
--
-- Security model (identical to 0004/0005/0006): RLS already enabled on puzzles; service_role
-- bypasses; no anon/authenticated policies.

begin;

alter table public.puzzles
  add column if not exists answer_kind text not null default 'phrase';

comment on column public.puzzles.answer_kind is
  'The answer modality (design/PUZZLE-DESIGNS.md §1): phrase|coords|url_token|code|behavior|'
  'object|spoken|none. DECLARATIVE metadata. phrase/coords/url_token are typed and matched by '
  'the resolver against accepted_answers; code/behavior/object/spoken are produced by a plugin '
  'listener that posts the sentinel token or sets the flag directly (no new resolver branch); '
  'none is a comprehension beat. Default ''phrase'' = the historical typed-solve path.';

commit;


-- ============================================================
-- FILE: seeds/puzzles_seed.sql
-- ============================================================

-- The Observance — PUZZLES SEED (realizes design/clue-web.md in the 0004 schema)
-- discord/supabase/seeds/puzzles_seed.sql
--
-- One INSERT per web node (design/clue-web.md §3). Every accepted_answers entry is
-- ALREADY NORMALIZED per ORACLE.md §2 (NFKC → lower → [^a-z0-9 ]→single space →
-- collapse ws → trim). The resolver normalizes player input the same way and tests
-- whole-string set-membership, so a raw "Bow, at!" or "-1280, 64" must equal one of
-- these stored strings AFTER normalization. Coordinate answers therefore appear in
-- BOTH unsigned and direction-word forms (the minus sign is dropped by step 3, so a
-- signed coord like "-1280 64" normalizes to "1280 64" — we store "1280 64" and also
-- the spoken bearing the carving gives).
--
-- Outcome wiring (ORACLE.md §3):
--   next_clue  → voice_key + next_puzzle_key (the door onward)
--   lore       → voice_key (+ voice_args.fragment) ONLY — a told secret, no door
--   dead_end   → voice_key ONLY — TRUE but opens nothing (no next, no beat)
--   side_quest → voice_key + next_puzzle_key (off-spine branch)
--   main_beat  → voice_key + 'unlock' beat {type,site_id,step,step_payload} + set_flags
--
-- Beats are enqueued status='approved' by the Oracle path (resolve.ts → the player
-- EARNED it; ORACLE.md §4). The "{solver}" mc_uuid placeholder is resolved to the
-- solving player's real uuid at enqueue time. beat.payload is real jsonb (not a
-- quoted string) — see ORACLE.md §4 "Plugin payload typing — RESOLVED".
--
-- IDEMPOTENT: ON CONFLICT (puzzle_key) DO UPDATE re-applies every authored field, so
-- re-running this file is safe and is the canonical way to edit a node. We touch the
-- 5 author-owned columns + active; created_at is left to the existing row.
--
-- Run AFTER 0004_oracle.sql, as service_role (RLS bypass — these are spoiler tables).

begin;

insert into public.puzzles
  (puzzle_key, title, accepted_answers, outcome_type, outcome_payload, movement, active, max_attempts)
values

